import { groupVariants, type VariantRun } from './variants'
import { cx, pct } from './util'

export type RunVariantsProps = {
  title: string
  runs: VariantRun[]
  /** The path the agent was meant to take. Without it, paths are only grouped and counted. */
  plan?: string[]
  className?: string
}

/**
 * Many runs grouped by the path they took, the way a process-mining variant view does. Each path says how many runs took
 * it, whether it followed the plan and what it skipped, and how often it failed with an exact interval, so a path that
 * failed 3 of 4 times is not mistaken for one that failed 300 of 400.
 */
export function RunVariants({ title, runs, plan, className }: RunVariantsProps) {
  const r = groupVariants(runs, plan)
  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <strong>{title}</strong>
        {r.conforming !== null && r.total > 0 && <span className="ol-pill" data-tone={r.conforming === r.total ? 'good' : 'warn'}>{r.conforming} of {r.total} followed the plan</span>}
      </div>
      <p className="ol-sub" style={{ margin: '0 0 6px' }}>{r.text}</p>
      {r.variants.length > 0 && (
        <ol className="ol-variants" aria-label="Paths, most common first">
          {r.variants.map((v, i) => (
            <li key={v.key} className="ol-variant" data-conforms={v.conforms === null ? undefined : String(v.conforms)}>
              <div className="ol-variantbar" aria-hidden="true"><span style={{ width: `${Math.max(2, v.share * 100)}%` }} /></div>
              <div className="ol-varianthead">
                <b>Path {i + 1}</b>
                <span className="ol-sub">{v.count} {v.count === 1 ? 'run' : 'runs'}, {pct(v.share, 0)}</span>
                {v.conforms === true && <span className="ol-pill" data-tone="good">Followed the plan</span>}
                {v.conforms === false && <span className="ol-pill" data-tone="warn">Left the plan</span>}
                {v.failed > 0 && <span className="ol-pill" data-tone="bad" title={`Exact interval ${pct(v.lower, 0)} to ${pct(v.upper, 0)}`}>Failed {v.failed} of {v.count} ({pct(v.lower, 0)} to {pct(v.upper, 0)})</span>}
              </div>
              <ol className="ol-varsteps">
                {v.steps.map((s, k) => <li key={`${k}-${s}`} data-extra={v.extra.includes(s)}>{s}</li>)}
              </ol>
              {(v.missing.length > 0 || v.outOfOrder) && (
                <p className="ol-sub ol-fielderr" style={{ margin: '4px 0 0' }}>
                  {v.missing.length > 0 && `Skipped: ${v.missing.join(', ')}. `}
                  {v.extra.length > 0 && `Not in the plan: ${v.extra.join(', ')}. `}
                  {v.outOfOrder && 'Some steps ran out of order.'}
                </p>
              )}
            </li>
          ))}
        </ol>
      )}
    </section>
  )
}

// Rules for grouping many runs by the path they took. The point of each: "how often did it follow the plan, and how
// often did each path fail" come from counting the runs, and each failure rate carries an exact interval, so a path
// that failed 3 of 4 times is not mistaken for one that failed 300 of 400.
import { clopperPearson } from '../verify/stats'

export type VariantRun = { id: string; /** What the run did, in order. */ steps: string[]; failed?: boolean }
export type Variant = {
  key: string
  steps: string[]
  runs: string[]
  count: number
  share: number
  failed: number
  failRate: number
  /** Exact interval on the failure rate. */
  lower: number
  upper: number
  /** `null` when no plan was given. */
  conforms: boolean | null
  missing: string[]
  extra: string[]
  outOfOrder: boolean
}
export type VariantReport = { variants: Variant[]; total: number; conforming: number | null; failed: number; text: string }

const norm = (s: string) => s.trim().toLowerCase().replace(/\s+/g, ' ')

export function groupVariants(runs: VariantRun[], plan?: string[], confidence = 0.95): VariantReport {
  const groups = new Map<string, VariantRun[]>()
  for (const r of runs) {
    const key = r.steps.map(norm).join(' > ')
    groups.set(key, [...(groups.get(key) ?? []), r])
  }
  const planned = plan?.map(norm)
  const variants = [...groups.entries()].map(([key, list]): Variant => {
    const steps = list[0]!.steps
    const have = steps.map(norm)
    const failed = list.filter((r) => r.failed).length
    const iv = clopperPearson(failed, list.length, confidence)
    let missing: string[] = []
    let extra: string[] = []
    let outOfOrder = false
    if (planned) {
      missing = plan!.filter((p) => !have.includes(norm(p)))
      extra = steps.filter((s) => !planned.includes(norm(s)))
      const order = have.filter((h) => planned.includes(h)).map((h) => planned.indexOf(h))
      outOfOrder = order.some((v, i) => i > 0 && v < order[i - 1]!)
    }
    return {
      key, steps, runs: list.map((r) => r.id), count: list.length, share: runs.length ? list.length / runs.length : 0, failed,
      failRate: failed / list.length, lower: iv.lower, upper: iv.upper,
      conforms: planned ? missing.length === 0 && extra.length === 0 && !outOfOrder : null, missing, extra, outOfOrder,
    }
  }).sort((a, b) => b.count - a.count || a.key.localeCompare(b.key))
  const failed = runs.filter((r) => r.failed).length
  const conforming = planned ? variants.filter((v) => v.conforms).reduce((n, v) => n + v.count, 0) : null
  const text = runs.length === 0
    ? 'No runs.'
    : `${runs.length} ${runs.length === 1 ? 'run' : 'runs'} took ${variants.length} ${variants.length === 1 ? 'path' : 'different paths'}.` +
      (conforming !== null ? ` ${conforming} followed the plan.` : '') +
      (failed ? ` ${failed} failed.` : '')
  return { variants, total: runs.length, conforming, failed, text }
}
